package com.prince.currencyexchange.entity; import java.io.Serializable; import java.util.Objects; public class CurrencyRateId implements Serializable { private String currencyCodeFrom; private String currencyCodeTo; public CurrencyRateId(){} public CurrencyRateId(String a,String b){currencyCodeFrom=a;currencyCodeTo=b;} @Override public boolean equals(Object o){ if(this==o) return true; if(!(o instanceof CurrencyRateId c)) return false; return Objects.equals(currencyCodeFrom,c.currencyCodeFrom)&&Objects.equals(currencyCodeTo,c.currencyCodeTo);} @Override public int hashCode(){return Objects.hash(currencyCodeFrom,currencyCodeTo);} }